import openpyxl
from collections import Counter
from datetime import datetime

# Load the workbook
wb = openpyxl.load_workbook('input.xlsx')

# Get the source sheet
source_sheet = wb['Imported Data']

# Read all data from the source sheet
# Assuming headers are in row 1
headers = []
for col in range(1, 6):  # Columns A to E
    headers.append(source_sheet.cell(row=1, column=col).value)

# Read data rows (starting from row 2)
data_rows = []
for row in range(2, source_sheet.max_row + 1):
    row_data = []
    for col in range(1, 6):
        cell_value = source_sheet.cell(row=row, column=col).value
        row_data.append(cell_value)
    # Skip empty rows
    if any(cell_value is not None for cell_value in row_data):
        data_rows.append(row_data)

# Column C is index 2 (0-based)
# Find duplicates in column C (Reference)
references = [row[2] for row in data_rows if row[2] is not None]
reference_counts = Counter(references)

# Filter rows where the reference appears more than once
duplicate_rows = [row for row in data_rows if row[2] is not None and reference_counts[row[2]] > 1]

# Sort duplicates by Balance (col E, index 4) and Invoiced Date (col D, index 3) in ascending order
# Need to handle date parsing for sorting
def parse_date(date_val):
    if date_val is None:
        return datetime.min
    if isinstance(date_val, datetime):
        return date_val
    if isinstance(date_val, str):
        # Try common formats
        for fmt in ('%Y-%m-%d %H:%M:%S', '%Y-%m-%d', '%d/%m/%Y', '%m/%d/%Y'):
            try:
                return datetime.strptime(date_val, fmt)
            except ValueError:
                continue
    return datetime.min

def parse_balance(balance_val):
    if balance_val is None:
        return 0
    if isinstance(balance_val, (int, float)):
        return balance_val
    if isinstance(balance_val, str):
        try:
            return float(balance_val)
        except ValueError:
            return 0
    return 0

# Sort by Balance ascending, then by Invoiced Date ascending
duplicate_rows.sort(key=lambda row: (parse_balance(row[4]), parse_date(row[3])))

# Create or clear the 'Duplicates' sheet
if 'Duplicates' in wb.sheetnames:
    del wb['Duplicates']
dup_sheet = wb.create_sheet('Duplicates')

# Write headers
for col_idx, header in enumerate(headers, 1):
    dup_sheet.cell(row=1, column=col_idx, value=header)

# Write duplicate rows
for row_idx, row_data in enumerate(duplicate_rows, 2):
    for col_idx, value in enumerate(row_data, 1):
        dup_sheet.cell(row=row_idx, column=col_idx, value=value)

# Save the workbook
wb.save('output.xlsx')
