# Get sheets
sheet1 = wb['Sheet1']
sheet2 = wb['Sheet2']

# Get the target date from Sheet1, Cell C5
target_date_cell = sheet1['C5']
target_date = target_date_cell.value

# Parse the target date if it's a string, otherwise it might be a datetime object
if isinstance(target_date, str):
    # Try common date formats
    for fmt in ('%Y-%m-%d %H:%M:%S', '%Y-%m-%d', '%m/%d/%Y', '%d/%m/%Y'):
        try:
            target_date = datetime.strptime(target_date, fmt)
            break
        except ValueError:
            continue

# Find the column in Sheet2 that matches the target date
# Dates are in row 5 of Sheet2, starting from column B (index 2)
target_col_idx = None
for col in range(2, sheet2.max_column + 1):
    cell_value = sheet2.cell(row=5, column=col).value
    if cell_value is None:
        continue
    # Normalize the cell value to datetime for comparison
    if isinstance(cell_value, str):
        for fmt in ('%Y-%m-%d %H:%M:%S', '%Y-%m-%d', '%m/%d/%Y', '%d/%m/%Y'):
            try:
                cell_date = datetime.strptime(cell_value, fmt)
                break
            except ValueError:
                continue
    elif isinstance(cell_value, datetime):
        cell_date = cell_value
    else:
        # Excel serial date number
        cell_date = datetime(1899, 12, 30) + timedelta(days=cell_value)

    # Compare dates (ignoring time part for robustness)
    if cell_date.date() == target_date.date():
        target_col_idx = col
        break

# If no matching column found, we can't proceed meaningfully, but let's handle it
if target_col_idx is None:
    # Default to showing "NEW" for all if no date match
    for row in range(6, 32):
        sheet1.cell(row=row, column=3).value = "NEW"
else:
    # For each item in Sheet1 column B (rows 6 to 31), look up in the target column of Sheet2
    for row in range(6, 32):
        item = sheet1.cell(row=row, column=2).value  # Column B

        # Look for this item in the target column of Sheet2 (rows 6 to 23)
        found = False
        for r in range(6, sheet2.max_row + 1):
            cell_value = sheet2.cell(row=r, column=target_col_idx).value
            if cell_value == item:
                found = True
                break

        if found:
            sheet1.cell(row=row, column=3).value = item
        else:
            sheet1.cell(row=row, column=3).value = "NEW"

# Save the workbook
wb.save('output.xlsx')
