import openpyxl
from datetime import datetime, timedelta

# Load the workbook
wb = openpyxl.load_workbook('input.xlsx')
ws = wb['Sheet1']

# Define the range to process (rows 2 to 100)
start_row = 2
end_row = 100

# Process each row
for row in range(start_row, end_row + 1):
    # Get values from columns A and B
    date_val = ws.cell(row=row, column=1).value
    std_val = ws.cell(row=row, column=2).value

    # Check if both A and B have data
    if date_val is not None and std_val is not None:
        try:
            # Parse the date from column A
            if isinstance(date_val, datetime):
                date_obj = date_val
            elif isinstance(date_val, str):
                # Try common date formats
                for fmt in ['%d-%b-%Y', '%Y-%m-%d', '%d/%m/%Y', '%m/%d/%Y']:
                    try:
                        date_obj = datetime.strptime(date_val, fmt)
                        break
                    except ValueError:
                        continue
                else:
                    date_obj = None
            else:
                date_obj = None

            # Parse the time from column B
            if isinstance(std_val, datetime):
                # If it's a datetime, extract the time part
                time_obj = std_val.time()
            elif isinstance(std_val, str):
                # Try to parse as time
                for fmt in ['%H:%M', '%H:%M:%S', '%I:%M %p', '%I:%M:%S %p']:
                    try:
                        time_obj = datetime.strptime(std_val, fmt).time()
                        break
                    except ValueError:
                        continue
                else:
                    time_obj = None
            else:
                time_obj = None

            if date_obj is not None and time_obj is not None:
                # Combine date and time
                std_datetime = datetime.combine(date_obj.date(), time_obj)

                # Calculate cut off time (30 minutes before STD)
                cut_off_datetime = std_datetime - timedelta(minutes=30)

                # Write the computed value to column C
                ws.cell(row=row, column=3).value = cut_off_datetime
            else:
                # If parsing failed, leave blank
                ws.cell(row=row, column=3).value = None
        except Exception:
            # If any error occurs, leave blank
            ws.cell(row=row, column=3).value = None
    else:
        # If either A or B is empty, set C to blank
        ws.cell(row=row, column=3).value = None

# Save the workbook
wb.save('output.xlsx')
